const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const salta = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.eq('ADM1_NAME', 'Salta'));

  const date1_start = '2000-12-01';
  const date1_end = '2000-12-31';
  const date2_start = '2019-12-01';
  const date2_end = '2019-12-31';

  // 2. Data Acquisition - MODIS Vegetation Continuous Fields
  const vcf2000 = ee.ImageCollection('MODIS/006/MOD44B')
    .filterBounds(salta)
    .filterDate(date1_start, date1_end);

  const vcf2019 = ee.ImageCollection('MODIS/006/MOD44B')
    .filterBounds(salta)
    .filterDate(date2_start, date2_end);

  // Check collection sizes
  const count2000 = vcf2000.size().getInfo();
  const count2019 = vcf2019.size().getInfo();

  console.log(`2000 Images: ${count2000}, 2019 Images: ${count2019}`);

  if (count2000 === 0 || count2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get first image from each collection
  const img2000 = vcf2000.first();
  const img2019 = vcf2019.first();

  // 3. Processing - Extract forest cover (Percent_Tree_Cover band)
  const forest2000 = img2000.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: salta,
    scale: 1000,
    maxPixels: 1e9
  }).get('Percent_Tree_Cover').getInfo();

  const forest2019 = img2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: salta,
    scale: 1000,
    maxPixels: 1e9
  }).get('Percent_Tree_Cover').getInfo();

  // Check for valid pixels
  const count2000_pixels = img2000.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: salta,
    scale: 1000,
    maxPixels: 1e9
  }).get('Percent_Tree_Cover').getInfo();

  const count2019_pixels = img2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: salta,
    scale: 1000,
    maxPixels: 1e9
  }).get('Percent_Tree_Cover').getInfo();

  console.log(`2000 Forest: ${forest2000?.toFixed(2)}%, Pixels: ${count2000_pixels}`);
  console.log(`2019 Forest: ${forest2019?.toFixed(2)}%, Pixels: ${count2019_pixels}`);

  // 4. Validation & Final Answer
  if (forest2000 === null || forest2019 === null || 
      isNaN(forest2000) || isNaN(forest2019) ||
      count2000_pixels === 0 || count2019_pixels === 0) {
    console.log("<answer>C3</answer>");
  } else if (forest2019 < forest2000 - 1.0) { // 1% threshold for meaningful decrease
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
